const achado = $input.all().map((i) => i.json).find((j) => j && j.id && !j.error);
if (!achado) return [{ json: { semCliente: true } }];
const f = achado.fields || {};
const b = $("Recebe pedido do app").first().json.body || {};
const contatoPedido = String(b.contatoId || "").trim();
const contatosDaEntidade = f.Contatos_Solicitantes || [];
const contatoId = (contatoPedido && contatosDaEntidade.includes(contatoPedido)) ? contatoPedido : (contatosDaEntidade[0] || "");
// Local escolhido pelo app quando o cliente tem mais de um endereco
// cadastrado (ver CONTEXTO.md 'Selecao de endereco', 14/09/2026) -- so
// aceita se o id mandado realmente pertence a essa entidade, senao usa o
// primeiro (mesmo comportamento de antes, pra clientes com 0 ou 1).
const localPedido = String(b.localId || "").trim();
const locaisDaEntidade = f.Locais_Atendimento || [];
const localId = (localPedido && locaisDaEntidade.includes(localPedido)) ? localPedido : (locaisDaEntidade[0] || "");
return [{ json: {
  clienteId: achado.id,
  clienteNome: f.Razao_Social_Nome || "",
  clienteDocumento: f.CPF_CNPJ || "",
  localId,
  contatoId,
} }];

// Limites do dia de trabalho, usados so pra sugestao de horario livre
// (o bloco reservado em si e sempre um "de tal hora ate tal hora" livre,
// escolhido direto pelo usuario -- nao ha mais periodo fixo nem duracao
// pre-definida). Ajustavel aqui se a rotina mudar.
const INICIO_DIA = "08:00", FIM_DIA = "18:00";

// Horario de Brasilia fixo (-03:00, sem horario de verao atualmente) --
// grava explicito pra nao depender de como o servidor interpreta data sem fuso.
function isoBrasilia(data, hhmm) { return data + "T" + hhmm + ":00-03:00"; }

// Extrai "HH:MM" em horario de Brasilia de qualquer ISO (vem em -03:00 ao
// montar aqui, mas vem em UTC/"Z" ao reler do Airtable) -- nao pode so
// cortar a string, tem que converter de verdade.
function horaLocalBrasilia(iso) {
  const d = new Date(new Date(iso).getTime() - 3 * 3600000);
  const hh = String(d.getUTCHours()).padStart(2, "0");
  const mm = String(d.getUTCMinutes()).padStart(2, "0");
  return hh + ":" + mm;
}

// Monta o bloco reservado a partir do inicio e fim escolhidos direto pelo
// usuario (ex: "13:30" ate "17:30") -- sem nenhum periodo/duracao
// pre-definido no meio do caminho.
function montaBloco(data, inicio, fim) {
  return { inicioIso: isoBrasilia(data, inicio), fimIso: isoBrasilia(data, fim) };
}

// Duas janelas de tempo se cruzam se uma comeca antes da outra terminar,
// nos dois sentidos.
function seCruzam(aIni, aFim, bIni, bFim) {
  return new Date(aIni) < new Date(bFim) && new Date(bIni) < new Date(aFim);
}

// Acha a primeira folga livre com a duracao pedida (em ms), comecando na
// data dada e olhando ate alguns dias a frente se o dia nao tiver espaco.
// ocupados e uma lista de { inicioIso, fimIso } (chamados ja marcados).
function achaHorarioLivre(dataInicial, duracaoMs, ocupados, ignorarId) {
  for (let d = 0; d < 10; d++) {
    const dia = new Date(dataInicial + "T00:00:00-03:00");
    dia.setUTCDate(dia.getUTCDate() + d);
    const dataStr = dia.toISOString().slice(0, 10);

    const doDia = ocupados
      .filter((o) => o.id !== ignorarId)
      .filter((o) => o.inicioIso.slice(0, 10) === dataStr || o.fimIso.slice(0, 10) === dataStr)
      .sort((a, b) => new Date(a.inicioIso) - new Date(b.inicioIso));

    let cursor = isoBrasilia(dataStr, INICIO_DIA);
    const fimDoDia = isoBrasilia(dataStr, FIM_DIA);
    for (const o of doDia) {
      if (new Date(o.inicioIso) - new Date(cursor) >= duracaoMs) {
        return montaSugestao(dataStr, cursor, duracaoMs);
      }
      if (new Date(o.fimIso) > new Date(cursor)) cursor = o.fimIso;
    }
    if (new Date(fimDoDia) - new Date(cursor) >= duracaoMs) {
      return montaSugestao(dataStr, cursor, duracaoMs);
    }
  }
  return null;
}

function montaSugestao(dataStr, cursor, duracaoMs) {
  const fimIso = new Date(new Date(cursor).getTime() + duracaoMs).toISOString();
  return { data: dataStr, inicio: horaLocalBrasilia(cursor), inicioIso: cursor, fim: horaLocalBrasilia(fimIso), fimIso };
}

const base = $("Monta ids do local e contato").first().json;
if (base.semCliente) return [{ json: { erro: "Cliente nao encontrado." } }];
const b = $("Recebe pedido do app").first().json.body || {};
const texto = (v) => String(v ?? "").trim();

const local = $("Busca local").all().map((i) => i.json).find((j) => j && j.id && !j.error) || {};
const lf = local.fields || {};

const contato = $("Busca contato").all().map((i) => i.json).find((j) => j && j.id && !j.error) || {};
const cf = contato.fields || {};
const linhas = (v) => (Array.isArray(v) ? v : String(v || "").split("\n")).map((s) => s.trim()).filter(Boolean);
const whatsapp = linhas(cf.WhatsApps)[0] || "";
const email = linhas(cf.Emails)[0] || "";

// Proximo numero sequencial: maior existente + 1 (comeca em 1 se a tabela
// estiver vazia). O Airtable nao cria autonumber por API, entao calculamos.
const todos = $("Busca todos os chamados").all().map((i) => i.json).filter((j) => j && j.id && !j.error);
const maiorNumero = todos.reduce((max, j) => Math.max(max, Number((j.fields || {}).Numero_Chamado) || 0), 0);
const numeroChamado = maiorNumero + 1;

const data = texto(b.data);
const reservadoInicio = texto(b.reservadoInicio);
const reservadoFim = texto(b.reservadoFim);
const temAgenda = Boolean(data && reservadoInicio && reservadoFim);
const bloco = temAgenda ? montaBloco(data, reservadoInicio, reservadoFim) : null;

const agora = new Date().toISOString();
const fields = {
  Numero_Chamado: numeroChamado,
  Cliente_Ref: [base.clienteId],
  Cliente_Nome: base.clienteNome,
  Cliente_Documento: base.clienteDocumento,
  Endereco_Copia: lf.Endereco_Completo || "",
  Contato_Nome: cf.Nome_Contato || "",
  Contato_WhatsApp: whatsapp,
  Contato_Email: email,
  Local_Exato: texto(b.localExato),
  Descricao_Solicitacao: texto(b.descricaoSolicitacao),
  Observacoes_Servico: texto(b.observacoesServico),
  Status: temAgenda ? "Agendado" : "Aguardando confirma\u00e7\u00e3o de data",
  Historico: agora + " -- Chamado #" + numeroChamado + " criado" + (temAgenda ? " e agendado." : ", sem data ainda."),
};
if (texto(b.horarioCombinadoCliente)) fields.Horario_Combinado_Cliente = texto(b.horarioCombinadoCliente);
if (bloco) { fields.Reservado_Inicio = bloco.inicioIso; fields.Reservado_Fim = bloco.fimIso; }

return [{ json: { metodo: "POST", url: "https://api.airtable.com/v0/app6PyYmtFduIMp7B/tbltipxOIw8F96QHO", corpo: { typecast: true, records: [{ fields }] }, numeroChamado } }];

const criado = $input.first().json;
const registro = (criado.records || [])[0];
if (!registro) return [{ json: { semRegistro: true } }];
const b = $("Recebe pedido do app").first().json.body || {};
let anexos = [];
try { anexos = JSON.parse(b.anexos || "[]"); } catch (e) { anexos = []; }
if (!Array.isArray(anexos)) anexos = [];
return anexos.map((a) => ({ json: {
  url: "https://content.airtable.com/v0/app6PyYmtFduIMp7B/" + registro.id + "/Anexos/uploadAttachment",
  corpo: { contentType: a.contentType, file: a.base64, filename: a.filename },
} }));

const criado = $("Cria o chamado").first().json;
const registro = (criado.records || [])[0] || {};
const numeroChamado = $("Monta o chamado").first().json.numeroChamado;
return [{ json: {
  ok: true,
  mensagem: "Chamado #" + numeroChamado + " criado!",
  id: registro.id || "",
  numeroChamado,
  status: (registro.fields || {}).Status || "",
} }];
